import {
  BaseSheet,
  FillRangeOperation,
  Sheet,
  Operation,
  InsertColOperation,
  RemoveColOperation,
  InsertRowOperation,
  RemoveRowOperation,
  ScatterRangeOperation,
} from '@bzl/sheet-js';
import { initialDoc } from '../utils';
import { SheetOTType } from '../../src';
import { describe, expect, test, afterEach, beforeEach } from 'vitest';

describe('测试OT冲突转换：left side to fill-range, right side to:', () => {
  let doc1: BaseSheet;
  let doc2: BaseSheet;
  const op1: FillRangeOperation = {
    type: 'fill-range',
    range: [4, 1, 4, 2],
    fillBy: 'style',
    style: {
      background: '#FAE1EB',
    },
    id: '1',
  };
  let op2: Operation;

  beforeEach(() => {
    doc1 = initialDoc() as Sheet;
    doc2 = initialDoc() as Sheet;
  });

  afterEach(() => {
    const [op12, op21] = SheetOTType.transformX([op1], [op2]);
    doc1 = SheetOTType.apply(SheetOTType.apply(doc1 as Sheet, op1) as Sheet, op21);
    doc2 = SheetOTType.apply(SheetOTType.apply(doc2 as Sheet, op2) as Sheet, op12);
    console.log('op1', JSON.stringify(op1));
    console.log('op2', JSON.stringify(op2));
    console.log('op12', JSON.stringify(op12));
    console.log('op21', JSON.stringify(op21));
    console.log('doc1', JSON.stringify(doc1));
    console.log('doc2', JSON.stringify(doc2));
    expect(doc1).toStrictEqual(doc2);
  });

  describe.concurrent('fill-range', () => {
    test('without intersection', () => {
      op2 = {
        type: 'fill-range',
        range: [1, 0, 1, 3],
        fillBy: 'style',
        style: {
          background: '#EFE1FA',
        },
        id: '1',
      };
    });
    test('same type', () => {
      op2 = {
        type: 'fill-range',
        range: [4, 0, 4, 3],
        fillBy: 'style',
        style: {
          background: '#EFE1FA',
        },
        id: '1',
      };
    });
    test('clear type', () => {
      op2 = {
        type: 'fill-range',
        range: [4, 0, 4, 3],
        fillBy: 'clear',
        style: {
          background: '#EFE1FA',
        },
        id: '1',
      };
    });
    test('different type', () => {
      op2 = {
        type: 'fill-range',
        fillBy: 'border',
        range: [4, 0, 4, 3],
        site: {
          top: true,
          right: true,
          bottom: true,
          left: true,
          innerCol: true,
          innerRow: true,
        },
        id: '1',
      };
    });
  });

  describe('insert-col', () => {
    describe('follow = before', () => {
      test('at before', () => {
        op2 = {
          type: 'insert-col',
          at: op1.range[0] - 1,
          count: 2,
          id: '1',
          follow: 'before',
        } as InsertColOperation;
      });

      test('at after', () => {
        op2 = {
          type: 'insert-col',
          at: op1.range[2] + 1,
          count: 2,
          id: '1',
          follow: 'before',
        } as InsertColOperation;
      });
      test('at same', () => {
        op2 = {
          type: 'insert-col',
          at: op1.range[0],
          count: 2,
          id: '1',
          follow: 'before',
        } as InsertColOperation;
      });
    });
    describe('follow = after', () => {
      test('at before', () => {
        op2 = {
          type: 'insert-col',
          at: op1.range[0] - 1,
          count: 2,
          id: '1',
          follow: 'after',
        } as InsertColOperation;
      });

      test('at after', () => {
        op2 = {
          type: 'insert-col',
          at: op1.range[2] + 1,
          count: 2,
          id: '1',
          follow: 'after',
        } as InsertColOperation;
      });
      test('at same', () => {
        op2 = {
          type: 'insert-col',
          at: op1.range[0],
          count: 2,
          id: '1',
          follow: 'after',
        } as InsertColOperation;
      });
    });
  });

  describe('remove-col', () => {
    test('at before without intersect', () => {
      op2 = {
        type: 'remove-col',
        at: 0,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
    test('at before with intersect', () => {
      op2 = {
        type: 'remove-col',
        at: op1.range[2] - 1,
        count: 3,
        id: '1',
      } as RemoveColOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'remove-col',
        at: op1.range[2] + 1,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'remove-col',
        at: op1.range[0],
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
  });

  describe.concurrent('insert-row', () => {
    describe('follow = after', () => {
      test('at before', () => {
        op2 = {
          type: 'insert-row',
          at: op1.range[1] - 1,
          count: 2,
          id: '1',
          follow: 'after',
        } as InsertRowOperation;
      });
      test('at after', () => {
        op2 = {
          type: 'insert-row',
          at: op1.range[3] + 1,
          count: 2,
          id: '1',
          follow: 'after',
        } as InsertRowOperation;
      });
      test('at same', () => {
        op2 = {
          type: 'insert-row',
          at: op1.range[3],
          count: 2,
          id: '1',
          follow: 'after',
        } as InsertRowOperation;
      });
    });
    describe('follow = before', () => {
      test('at before', () => {
        op2 = {
          type: 'insert-row',
          at: op1.range[1] - 1,
          count: 2,
          id: '1',
          follow: 'before',
        } as InsertRowOperation;
      });
      test('at after', () => {
        op2 = {
          type: 'insert-row',
          at: op1.range[3] + 1,
          count: 2,
          id: '1',
          follow: 'before',
        } as InsertRowOperation;
      });
      test('at same', () => {
        op2 = {
          type: 'insert-row',
          at: op1.range[3],
          count: 2,
          id: '1',
          follow: 'before',
        } as InsertRowOperation;
      });
    });
  });

  describe('remove-row', () => {
    test('at before', () => {
      op2 = {
        type: 'remove-row',
        at: op1.range[1] - 1,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'remove-row',
        at: op1.range[3] + 1,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'remove-row',
        at: op1.range[3],
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
  });

  describe('scatter-range', () => {
    test.concurrent('style type', () => {
      op2 = {
        type: 'scatter-range',
        range: [2, 0, 3, 3],
        refs: {
          cells: [
            {
              children: [
                {
                  meta: {
                    background: '#13C2C2',
                  },
                  index: 3,
                },
              ],
              index: 0,
            },
            {
              children: [
                {
                  meta: {
                    background: '#13C2C2',
                  },
                  index: 3,
                },
              ],
              index: 0,
            },
            {
              children: [
                {
                  meta: {
                    background: '#13C2C2',
                  },
                  index: 3,
                },
              ],
              index: 0,
            },
            {
              children: [
                {
                  index: 2,
                },
                {
                  meta: {
                    background: '#13C2C2',
                  },
                  index: 3,
                },
              ],
              index: 0,
            },
            {
              children: [
                {
                  meta: {
                    background: '#13C2C2',
                  },
                  index: 3,
                },
              ],
              index: 1,
            },
            {
              children: [
                {
                  meta: {
                    background: '#13C2C2',
                  },
                  index: 3,
                },
              ],
              index: 1,
            },
            {
              children: [
                {
                  meta: {
                    background: '#13C2C2',
                  },
                  index: 3,
                },
              ],
              index: 1,
            },
            {
              children: [
                {
                  meta: {
                    background: '#13C2C2',
                  },
                  index: 3,
                },
              ],
              index: 1,
            },
            {
              children: [
                {
                  index: 2,
                },
                {
                  meta: {
                    background: '#13C2C2',
                  },
                  index: 3,
                },
              ],
              index: 1,
            },
            {
              children: [
                {
                  meta: {
                    background: '#13C2C2',
                  },
                  index: 3,
                },
              ],
              index: 1,
            },
            {
              children: [
                {
                  meta: {
                    background: '#13C2C2',
                  },
                  index: 3,
                },
              ],
              index: 1,
            },
            {
              children: [
                {
                  meta: {
                    background: '#13C2C2',
                  },
                  index: 3,
                },
              ],
              index: 2,
            },
            {
              children: [
                {
                  index: 2,
                },
                {
                  meta: {
                    background: '#13C2C2',
                  },
                  index: 3,
                },
              ],
              index: 2,
            },
            {
              index: 3,
              children: [
                {
                  index: 2,
                },
                {
                  index: 3,
                },
              ],
            },
          ],
          rows: [],
          cols: [],
          sheet: {},
        },
        scatterBy: 'style',
        id: '1',
      } as ScatterRangeOperation;
    });
    test.concurrent('cell type', () => {
      op2 = {
        type: 'scatter-range',
        range: [0, 2, null, 2],
        refs: {
          cells: [
            {
              children: [
                {
                  meta: {
                    type: 'number',
                    value: 2,
                  },
                  index: 1,
                },
              ],
              index: 2,
            },
          ],
        },
        scatterBy: 'data',
        id: '1',
      } as ScatterRangeOperation;
    });
  });
});
